eroKron 1\\n          ((S.strategyMeasurement .bob question).effect a))\\n        S.toStrategy.ψ ≤ C * ε := WinImplications.win_cons_proof\\n\\n/-- The low-degree subtest bounds completed line-evaluation classes against\\ncompleted point measurements. This is item 2 of\\n`lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:200-204`, blueprint\\n`ch14_qpbt_observables.tex:523-548`. -/\\ntheorem win_low_degree :\\n    ∃ C : ℝ, 1 ≤ C ∧\\n      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε),\\n      0 ≤ ε → ∀ W : PauliKind,\\n      consistencyDefect (linePointDist P.toLdParams)\\n        (fun sample a => heteroKron\\n          ((S.lineEvalMeas .alice W sample.1 sample.2).effect a) 1)\\n        (fun sample a => heteroKron 1\\n          ((S.pointMeasOption .bob W sample.2).effect a))\\n        S.toStrategy.ψ ≤ C * ε := WinImplications.win_low_degree_proof\\n\\n/-- The Pauli-basis consistency subtest compares point values with evaluated\\nlow-degree encodings of Pauli answers. This is item 3 of\\n`lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:205-209`, blueprint\\n`ch14_qpbt_observables.tex:549-566`. -/\\ntheorem win_pauli_basis_cons :\\n    ∃ C : ℝ, 1 ≤ C ∧\\n      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε),\\n      0 ≤ ε → ∀ W : PauliKind,\\n      consistencyDefect (uniformDistribution (Fin P.m → PauliScalar P))\\n        (fun u a => heteroKron ((S.pointMeas .alice W u).effect a) 1)\\n        (fun u a => heteroKron 1 ((S.pauliEvalMeas .bob W u).effect a))\\n        S.toStrategy.ψ ≤ C * ε := WinImplications.win_pauli_basis_cons_proof\\n\\n/-- On commuting tuples, Pair/W answers agree with the corresponding\\ncomponent of Pair answers. This is item 4 of `lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:210-231`, blueprint\\n`ch14_qpbt_observables.tex:567-582`. -/\\ntheorem win_comm :\\n    ∃ C : ℝ, 1 ≤ C ∧\\n      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε),\\n      0 ≤ ε → ∀ W : PauliKind,\\n      consistencyDefect (commTupleDist P)\\n        (fun ω a => heteroKron\\n          ((S.pairWMeas .alice W ω.1 ω.2.1 ω.2.2.1 ω.2.2.2).effect a) 1)\\n        (fun ω a => heteroKron 1 ((S.pairComponentMeas .bob W ω).effect a))\\n        S.toStrategy.ψ ≤ C * ε := WinImplications.win_comm_proof\\n\\n/-- On commuting tuples, trace-coarse-grained point answers agree with Pair/W\\nanswers. This is item 5 of `lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:232-239`, blueprint\\n`ch14_qpbt_observables.tex:583-598`. -/\\n\",\"exit_code\":0,\"status\":\"completed\"}}\n{\"type\":\"item.started\",\"item\":{\"id\":\"item_58\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"rg -n \\\\\\\"transpose_sum|transpose_finset|transpose_smul|transpose_vecMulVec|vecMulVec_transpose\\\\\\\" .lake/packages/mathlib/Mathlib/Data/Matrix MIPStarRE -g '*.lean' | head -100\\\"\",\"aggregated_output\":\"\",\"exit_code\":null,\"status\":\"in_progress\"}}\n{\"type\":\"item.completed\",\"item\":{\"id\":\"item_57\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"sed -n '260,325p' MIPStarRE/QPBT/Games/DistanceTheorems.lean\\\"\",\"aggregated_output\":\"  unfold stateQForm applyOperatorToState\\n  rw [EuclideanSpace.inner_eq_star_dotProduct, EuclideanSpace.inner_eq_star_dotProduct]\\n  change (Complex.re (∑ j : J,\\n      (∑ k : J, reindexOp e.symm M j k * (reindexState e ψ).ofLp k) *\\n        star (reindexState e ψ).ofLp j)) =\\n    Complex.re (∑ i : I, (∑ k : I, M i k * ψ.ofLp k) * star (ψ.ofLp i))\\n  simp_rw [hop, hstate, hstate_star]\\n  apply congrArg Complex.re\\n  have hinner (j : J) :\\n      (∑ k : J, M (e.symm j) (e.symm k) * ψ.ofLp (e.symm k)) =\\n        ∑ k : I, M (e.symm j) k * ψ.ofLp k :=\\n    e.symm.sum_comp (fun k : I => M (e.symm j) k * ψ.ofLp k)\\n  calc\\n    (∑ j : J, (∑ k : J, M (e.symm j) (e.symm k) * ψ.ofLp (e.symm k)) *\\n        star (ψ.ofLp (e.symm j))) =\\n      ∑ j : J, (∑ k : I, M (e.symm j) k * ψ.ofLp k) *\\n        star (ψ.ofLp (e.symm j)) := by simp_rw [hinner]\\n    _ = ∑ i : I, (∑ k : I, M i k * ψ.ofLp k) * star (ψ.ofLp i) :=\\n      e.symm.sum_comp (fun i : I => (∑ k : I, M i k * ψ.ofLp k) * star (ψ.ofLp i))\\n\\n/-- The product POVM whose effects are Kronecker products of the two factor effects. -/\\nprivate noncomputable def tensorMeasurement\\n    {α β I J : Type*} [Fintype α] [Fintype β]\\n    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\\n    (A : Measurement α I) (B : Measurement β J) :\\n    Measurement (α × β) (I × J) :=\\n  Measurement.ofSumEqOne\\n    (fun ab => heteroKron (A.effect ab.1) (B.effect ab.2))\\n    (fun ab => MIPStarRE.Quantum.kronecker_nonneg (A.pos ab.1) (B.pos ab.2))\\n    (by\\n      change ∑ ab : α × β, opTensor (A.effect ab.1) (B.effect ab.2) = 1\\n      rw [Fintype.sum_prod_type]\\n      calc\\n        (∑ a : α, ∑ b : β, opTensor (A.effect a) (B.effect b)) =\\n            ∑ a : α, leftTensor (A.effect a) *\\n              (∑ b : β, rightTensor (B.effect b)) := by\\n          apply Finset.sum_congr rfl\\n          intro a _\\n          rw [Matrix.mul_sum]\\n          apply Finset.sum_congr rfl\\n          intro b _\\n          exact (leftTensor_mul_rightTensor_eq_opTensor _ _).symm\\n        _ = 1 := by\\n          rw [rightTensor_finset_sum, B.sum_eq_one, rightTensor_one]\\n          simp_rw [Matrix.mul_one]\\n          rw [leftTensor_finset_sum, A.sum_eq_one, leftTensor_one])\\n\\n/-- The product of two projective POVMs is projective. -/\\nprivate theorem tensorMeasurement_isProjective\\n    {α β I J : Type*} [Fintype α] [Fintype β]\\n    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\\n    (A : Measurement α I) (B : Measurement β J)\\n    (hA : MIPStarRE.QPBT.Measurement.IsProjective A)\\n    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) :\\n    MIPStarRE.QPBT.Measurement.IsProjective (tensorMeasurement A B) := by\\n  intro ab\\n  change IsProj (Matrix.kronecker (A.