and_execution\",\"command\":\"/bin/bash -lc \\\"sed -n '1,115p' MIPStarRE/QPBT/Observables/WinImplications/Consistency.lean\\\"\",\"aggregated_output\":\"\",\"exit_code\":null,\"status\":\"in_progress\"}}\n{\"type\":\"item.completed\",\"item\":{\"id\":\"item_66\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"sed -n '1,125p' MIPStarRE/QPBT/Observables/WinImplications/Setup.lean\\\"\",\"aggregated_output\":\"\",\"exit_code\":0,\"status\":\"completed\"}}\n{\"type\":\"item.started\",\"item\":{\"id\":\"item_68\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"sed -n '130,230p' MIPStarRE/QPBT/Observables/WinImplications/Setup.lean\\\"\",\"aggregated_output\":\"\",\"exit_code\":null,\"status\":\"in_progress\"}}\n{\"type\":\"item.started\",\"item\":{\"id\":\"item_69\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"rg -n \\\\\\\"pauliQuestionMarginal.*point|avgOver.*pauliQuestionMarginal|Distribution.*pointQuestion|pointQuestion.*pauliQuestionMarginal\\\\\\\" MIPStarRE/QPBT -g '*.lean'\\\"\",\"aggregated_output\":\"\",\"exit_code\":null,\"status\":\"in_progress\"}}\n{\"type\":\"item.started\",\"item\":{\"id\":\"item_70\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"git show --stat --oneline 407654a && git show --stat --oneline 9a4ff99 && git show 407654a:MIPStarRE/QPBT/Observables/PointConsistency.lean | sed -n '75,135p'\\\"\",\"aggregated_output\":\"\",\"exit_code\":null,\"status\":\"in_progress\"}}\n{\"type\":\"item.completed\",\"item\":{\"id\":\"item_67\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"sed -n '1,115p' MIPStarRE/QPBT/Observables/WinImplications/Consistency.lean\\\"\",\"aggregated_output\":\"import MIPStarRE.QPBT.Observables.WinImplications.MagicSquare\\n\\n/-!\\n# Exact consistency winning implication\\n\\nThis module proves the exact same-question consistency bound for the two\\nplayers' Pauli-test measurements.\\n\\n## References\\n\\nThe proof infrastructure in this module supports `lem:qld-win-implications`\\nfrom `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:192-267`\\nand `blueprint/src/chapter/ch14_qpbt_observables.tex:505-660`.\\n-/\\n\\nopen scoped BigOperators Matrix ComplexOrder\\n\\nnamespace MIPStarRE.QPBT\\n\\nopen MIPStarRE.LDT hiding Measurement\\nopen MIPStarRE.Quantum\\n\\nnoncomputable section\\n\\nnamespace WinImplications\\n\\nlocal instance pauliEdgeNonemptyConsistency : Nonempty PauliEdge := pauliEdge_nonempty\\n\\n/-- The self-loop verifier edge at one Pauli question type. -/\\ndef pauliLoopEdge (t : PauliType) : PauliEdge :=\\n  ⟨(t, t), by simp [pauliEdges]⟩\\n\\n/-- Answer-mismatch mass at the first question generated by one sampler edge. -/\\nnoncomputable def firstQuestionMismatch {P : AdmissibleParams} {ε : ℝ}\\n    (S : ProjectiveSetting P ε) (e : PauliEdge) (z : PauliSpace P) : ℝ :=\\n  outcomeEventWeight S.toStrategy\\n    (e.1.1, pauliCL P e.1.1 z) (e.1.1, pauliCL P e.1.1 z)\\n    (fun A B => A ≠ B)\\n\\n/-- Unequal answers to the same sampled question are rejected on its self-loop. -/\\ntheorem loopMismatch_le_rejection {P : AdmissibleParams} {ε : ℝ}\\n    (S : ProjectiveSetting P ε) (t : PauliType) (z : PauliSpace P) :\\n    outcomeEventWeight S.toStrategy\\n        (t, pauliCL P t z) (t, pauliCL P t z) (fun A B => A ≠ B) ≤\\n      pauliRejectionAt S.toStrategy (pauliLoopEdge t) z := by\\n  unfold pauliRejectionAt pauliSourceQuestions pauliLoopEdge\\n  dsimp\\n  apply outcome_event_weight_mono\\n  intro A B hne\\n  simp only [pauliBasisTest]\\n  simp only [pauliWinPredicate, Bool.and_eq_true, ↓reduceIte,\\n    Bool.if_false_right, Bool.decide_and, Bool.decide_eq_true,\\n    Bool.and_eq_false_imp, decide_eq_false_iff_not, and_imp]\\n  intro _ _\\n  exact hne\\n\\n/-- Strategy consistency is the same-question answer-mismatch probability. -/\\ntheorem strategyConsistency_eq_mismatch {P : AdmissibleParams} {ε : ℝ}\\n    (S : ProjectiveSetting P ε) :\\n    consistencyDefect (pauliQuestionMarginal P)\\n        (fun question a => heteroKron\\n          ((S.strategyMeasurement .alice question).effect a) 1)\\n        (fun question a => heteroKron 1\\n          ((S.strategyMeasurement .bob question).effect a))\\n        S.toStrategy.ψ =\\n      avgOver (pauliQuestionMarginal P) (fun question =>\\n        outcomeEventWeight S.toStrategy question question (fun A B => A ≠ B)) := by\\n  change consistencyDefect (pauliQuestionMarginal P)\\n      (fun question a => heteroKron ((S.toStrategy.A question).effect a)\\n        (1 : Op S.toStrategy.ιB))\\n      (fun question a => heteroKron (1 : Op S.toStrategy.ιA)\\n        ((S.toStrategy.B question).effect a))\\n      S.toStrategy.ψ = _\\n  unfold consistencyDefect outcomeEventWeight\\n  apply avgOver_congr\\n  intro question\\n  simp only [DistanceCalculus.consistency_term_eq_stateQForm]\\n  simp_rw [DistanceCalculus.placed_product_stateQForm_eq]\\n  apply Finset.sum_congr rfl\\n  intro A _\\n  apply Finset.sum_congr rfl\\n  intro B _\\n  by_cases hAB : A = B\\n  · simp [hAB]\\n  · simp [hAB, DistanceCalculus.stateQForm, outcomeWeight,\\n      applyOperatorToState]\\n\\n/-- The consistency subtest bounds the off-diagonal defect of the two strategy\\nmeasurement families. This is item 1 of `lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:197-199`, blueprint\\n`ch14_qpbt_observables.tex:515-522`. -/\\ntheorem win_cons_proof :\\n    ∃ C : ℝ, 1 ≤ C ∧\\n      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε),\\n      0 ≤ ε →\\n      consistencyDefect (pauliQuestionMarginal P)\\n        (fun question a => heteroKron\\n          ((S.strategyMeasurement .alice question).effect a) 1)\\n        (fun question a => heteroKron 1\\n          ((S.strategyMeasurement .bob question).effect a))\\n        S.toStrategy.ψ ≤ C * ε := by\\n  refine ⟨(Fintype.card PauliEdge : ℝ), ?_, ?_⟩\\n  · exact_mod_cast (Fintype.card_pos : 0 < Fintype.card PauliEdge)\\n  intro P ε S _\\n  rw [strategyConsistency_eq_mismatch]\\n  unfold pauliQuestionMarginal pauliQuestionDistribution\\n  rw [Distribution.avgOver_map, Distribution.avgOver_map]\\n  change avgOver (uniformDistribution (PauliEdge × PauliSpace P))\\n      (fun ez => firstQuestionMismatch S ez.1 ez.2) ≤ _\\n  rw [avgOver_uniform_prod]\\n  calc\\n    avgOver (uniformDistribution PauliEdge) (fun e =>\\n        avgOver (uniformDistribution (PauliSpace P)) (fun z =>\\n          firstQuestionMismatch S e z)) ≤\\n      avgOver (uniformDistribution PauliEdge)\\n\",\"exit_code\":0,\"status\":\"completed\"}}\n{\"type\":\"item.completed\",\"item\":{\"id\":\"item_68\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"sed -n '130,230p' MIPStarRE/QPBT/Observables/WinImplications/Setup.lean\\\"\",\"aggregated_output\":\"`M^((Point,W),u)_[tr(·r)=a]` in items 5 and 7 of\\n`lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:232-263`, blueprint\\n`ch14_qpbt_observables.tex:583-660`. -/\\nnoncomputable def pointTraceMeas (S : ProjectiveSetting P ε)\\n    (side : PlayerSide) (W : PauliKind) (u : Fin P.m → PauliScalar P)\\n    (r : PauliScalar P) : Measurement (ZMod 2) (S.LocalSpace side) :=\\n  (S.pointMeas side W u).postprocess fun a => fixedBinTrace P.model (a * r)\\n\\n/-- Evaluate a Pauli-register answer through its low-degree encoding at `u`.\\nThis is `M^(Pauli,W)_[g_h(u)=a]` in item 3 of\\n`lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:205-209`, blueprint\\n`ch14_qpbt_observables.tex:549-566`. -/\\nnoncomputable def pauliEvalMeas (S : ProjectiveSetting P ε)\\n    (side : PlayerSide) (W : PauliKind) (u : Fin P.m → PauliScalar P) :\\n    Measurement (PauliScalar P) (S.LocalSpace side) :=\\n  (S.pauliMeas side W).postprocess fun h => lowDegreeEnc h u\\n\\n/-- Select the `W` bit of a Pair answer. This is the bracketed Pair family in\\nitem 4 of `lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:210-231`, blueprint\\n`ch14_qpbt_observables.tex:567-582`. -/\\nnoncomputable def pairComponentMeas (S : ProjectiveSetting P ε)\\n    (side : PlayerSide) (W : PauliKind) (ω : PauliTuple P) :\\n    Measurement (ZMod 2) (S.LocalSpace side) :=\\n  (S.pairMeas side ω.1 ω.2.1 ω.2.2.1 ω.2.2.2).postprocess fun bits =>\\n    match W with\\n    | .X => bits.1\\n    | .Z => bits.2\\n\\n/-- The bit measurement for a Magic Square variable question. This is\\n`M^(Variable_j,omega)_a` in item 7 of `lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:250-263`, blueprint\\n`ch14_qpbt_observables.tex:626-660`. -/\\nnoncomputable def msVarBitMeas (S : ProjectiveSetting P ε)\\n    (side : PlayerSide) (j : Fin 9) (ω : PauliTuple P) :\\n    Measurement (ZMod 2) (S.LocalSpace side) :=\\n  (S.msMeas side (.var j) ω.1 ω.2.1 ω.2.2.1 ω.2.2.2).postprocess msBitOrZero\\n\\n/-- The Magic Square strategy induced by the test measurements at a fixed\\nPauli tuple. It retains the original heterogeneous local spaces and state, as\\nrequired by item 6 of `lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:240-249`, blueprint\\n`ch14_qpbt_observables.tex:599-625`. -/\\nnoncomputable def msStrategyAt (S : ProjectiveSetting P ε)\\n    (ω : PauliTuple P) : Strategy msGame where\\n  ιA := S.toStrategy.ιA\\n  ιB := S.toStrategy.ιB\\n  ψ := S.toStrategy.ψ\\n  ψ_norm := S.toStrategy.ψ_norm\\n  A t := S.msMeas .alice t ω.1 ω.2.1 ω.2.2.1 ω.2.2.2\\n  B t := S.msMeas .bob t ω.1 ω.2.1 ω.2.2.1 ω.2.2.2\\n\\n/-- The Magic Square value `Lambda_omega` is the ordinary tensor-product game\\nvalue of `msStrategyAt`. This is item 6 of `lem:qld-win-implications`, paper\\n`14_analysis_of_the_pauli_basis_test.tex:240-249`, blueprint\\n`ch14_qpbt_observables.tex:599-625`. -/\\nnoncomputable def msValueAt (S : ProjectiveSetting P ε) (ω : PauliTuple P) : ℝ :=\\n  (S.msStrategyAt ω).value\\n\\nend ProjectiveSetting\\n\\nend\\n\\nend MIPStarRE.QPBT\\n\",\"exit_code\":0,\"status\":\"completed\"}}\n{\"type\":\"item.completed\