clideanSpace ℂ ι,\\n      inner ℂ w (applyOperatorToState A z) =\\n        inner ℂ (applyOperatorToState R w) (applyOperatorToState R z) := by\\n    intro w z\\n    have h := LinearMap.adjoint_inner_right (Matrix.toEuclideanLin R) w\\n      (Matrix.toEuclideanLin R z)\\n    rw [hadjoint] at h\\n    rw [← hRR, applyOperatorToState_mul]\\n    exact h\\n  have hnorm : ∀ w : EuclideanSpace ℂ ι,\\n      ‖applyOperatorToState R w‖ =\\n        Real.sqrt (inner ℂ w (applyOperatorToState A w)).re := by\\n    intro w\\n    have h2 : ‖applyOperatorToState R w‖ ^ 2 =\\n        (inner ℂ (applyOperatorToState R w) (applyOperatorToState R w)).re := by\\n      rw [@norm_sq_eq_re_inner ℂ]\\n      rfl\\n    rw [hsplit, ← h2, Real.sqrt_sq (norm_nonneg _)]\\n  rw [hsplit, ← hnorm, ← hnorm]\\n  exact norm_inner_le_norm _ _\\n\\n/-- The sum over outcomes of the real parts of `⟨u a, A a (v a)⟩`, for\\npositive weights `A a`, is bounded by the product of the square roots of the\\ntwo diagonal sums. -/\\ntheorem abs_sum_re_inner_le_sqrt_mul_sqrt {α ι : Type*} [Fintype α]\\n    [Fintype ι] [DecidableEq ι] (A : α → Op ι) (hA : ∀ a, 0 ≤ A a)\\n    (u v : α → EuclideanSpace ℂ ι) :\\n    |∑ a, (inner ℂ (u a) (applyOperatorToState (A a) (v a))).re| ≤\\n      Real.sqrt (∑ a, (inner ℂ (u a) (applyOperatorToState (A a) (u a))).re) *\\n        Real.sqrt (∑ a, (inner ℂ (v a) (applyOperatorToState (A a) (v a))).re) := by\\n  have hu : ∀ a, 0 ≤ (inner ℂ (u a) (applyOperatorToState (A a) (u a))).re :=\\n\",\"exit_code\":0,\"status\":\"completed\"}}\n/home/drx/.cache/mipstarre-dev/reviews/pr400/79caf482f3bb07bf4392bccacf0f2384adf8fb8f/prose-last-message.md.dispatch.log:58:{\"type\":\"item.completed\",\"item\":{\"id\":\"item_28\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"sed -n '315,470p' MIPStarRE/QPBT/Combining/Defs.lean\\\"\",\"aggregated_output\":\"        (combineLinePolynomial aX bX aZ bZ uα vα uβ vβ f g).eval t := by\\n    rw [Polynomial.eval_eq_sum_range' (n := c + 1 + 1) (by omega) t]\\n    simp only [evalCoefficient, combineLinePoly]\\n    exact Fin.sum_univ_eq_sum_range\\n      (fun k =>\\n        (combineLinePolynomial aX bX aZ bZ uα vα uβ vβ f g).coeff k * t ^ k)\\n      (c + 1 + 1)\\n  rw [heval, combineLinePolynomial]\\n  simp only [Polynomial.eval_add, Polynomial.eval_mul, Polynomial.eval_C,\\n    Polynomial.eval_X, Polynomial.eval_comp, linePolynomialOfCoefficients_eval]\\n  ring\\n\\n/-- The seed event defining the `i`-th original-dimensional restricted line\\nlaw.  It is applied before the `LineDesc` decoder, since a geometric line does\\nnot determine the retained seed. -/\\ndef restrictedLineSeedEvent (L : LdParams) (i : Fin L.m)\\n    (sample : LdSpace L × LdSpace L) : Prop :=\\n  chiIndex L sample.1.seed = i\\n\\n/-- Decidability of the pre-decoding seed event. -/\\ninstance restrictedLineSeedEvent_decidablePred (L : LdParams) (i : Fin L.m) :\\n    DecidablePred (restrictedLineSeedEvent L i) := by\\n  intro sample\\n  unfold restrictedLineSeedEvent\\n  infer_instance\\n\\n/-- Formalization-only auxiliary for `def:ith-restricted-line`: whenever a line\\nCL map keeps the shared scalar coordinate, the pre-decoding law it generates\\nagainst the point map gives positive mass to every coordinate-index event.  The\\nwitness is the constant seed reconstructed from the index by\\n`seedOfIndexResidue`. -/\\nprivate theorem clDistribution_seedEvent_positive (L : LdParams) (i : Fin L.m)\\n    (CL : LdSpace L → LdSpace L)\\n    (hseed : ∀ z : LdSpace L, (CL z).seed = z.seed) :\\n    0 < ∑ sample ∈\\n        (clDistribution CL (ldPointCL L)).support.filter\\n          (restrictedLineSeedEvent L i),\\n      (clDistribution CL (ldPointCL L)).weight sample := by\\n  set s0 : ScalarQ L := seedOfIndexResidue L i ⟨0, L.seedFiberCard_pos⟩ with hs0\\n  set z0 : LdSpace L := fun _ => s0 with hz0\\n  refine Finset.sum_pos'\\n    (fun a _ => (clDistribution CL (ldPointCL L)).nonnegative a)\\n    ⟨(CL z0, ldPointCL L z0), Finset.mem_filter.mpr ⟨?_,