tribution (LinePointPairSample P)) (hν : ν.IsProbability) (η ζ : ℝ)\\n   457\\t    (hcons : consistencyDefect ν\\n   458\\t      (fun s o => S.place .AA'\\n   459\\t        (((lines.T .alice s.1.1 s.2.1).postprocess fun fs =>\\n   460\\t          (evalOpt s.1.1 s.1.2 fs.1, evalOpt s.2.1 s.2.2 fs.2)).effect o))\\n   461\\t      (fun s o => S.place .BA''\\n   462\\t        (((points.Q .bob s.1.2 s.2.2).postprocess fun ab =>\\n   463\\t          (some ab.1, some ab.2)).effect o))\\n   464\\t      S.psiHat ≤ η)\\n   465\\t    (hZX : opFamilyDistSq ν\\n   466\\t      (fun s o => S.place .BA''\\n   467\\t        (((points.Q .bob s.1.2 s.2.2).postprocess fun ab =>\\n   468\\t          (some ab.1, some ab.2)).effect o))\\n   469\\t      (fun s o => S.place .BA''\\n   470\\t        ((S.pointMeasExpOption .bob .Z s.2.2).effect o.2 *\\n   471\\t          (S.pointMeasExpOption .bob .X s.1.2).effect o.1))\\n   472\\t      S.psiHat ≤ ζ) :\\n   473\\t    1 - avgOver ν (fun s =>\\n   474\\t      ∑ o : Option (PauliScalar P) × Option (PauliScalar P),\\n   475\\t        stateQForm S.psiHat\\n   476\\t          (S.place .AA'\\n   477\\t            (((lines.T .alice s.1.1 s.2.1).postprocess fun fs =>\\n   478\\t              (evalOpt s.1.1 s.1.2 fs.1, evalOpt s.2.1 s.2.2 fs.2)).effect o) *\\n   479\\t            S.place .BA'' ((S.pointMeasExpOption .bob .Z s.2.2).effect o.2))) ≤\\n   480\\t      2 * Real.sqrt η + 2 * Real.sqrt ζ := by\\n   481\\t  exact lines.one_sub_Z_overlap_le_at .AA' .BA'' trivial ν hν η ζ hcons hZX\\n   482\\t\\n   483\\t\\n   484\\tend Placed\\n   485\\t\\n   486\\t/-! ## The two deficits over a product of restricted line-point laws -/\\n   487\\t\\n   488\\t/-- Every restricted line-point law has total mass one. -/\\n   489\\ttheorem restrictedLinePointDist_isProbability (P : AdmissibleParams)\\n   490\\t    (kind : LineKind) (i : Fin P.m) :\\n   491\\t    (restrictedLinePointDist P kind i).IsProbability := by\\n   492\\t  cases kind\\n   493\\t  · change (restr